// Scoped to PSRI only for the IVR=1 (Appointement/Other) Inbound recompute --
// other processes' logic is unchanged by that fix, so no need to re-run them.
// Edit serviceIds back to the full list below for a general backfill.
// const serviceIds = '1287,489,338,2023,741,295,1702,805'; // PSRI, Baxter, Nihon, ONDC, Infres, VMM, ResMed, LOTS
const serviceIds = '1287';
const from = '2026-08-01';
const to = '2026-09-30';
return [{ json: { serviceIds, from, to } }];

const from = $('Set Date Range').first().json.from, to = $('Set Date Range').first().json.to, serviceIds = $('Set Date Range').first().json.serviceIds;
const query = `UPDATE calls.combined_summary cs
JOIN calls.dim_process dp ON dp.process_name = cs.process_name
JOIN (
  SELECT cd.service_id, cd.missed_by AS agent_name, cd.call_date, COUNT(*) AS agent_missed_ib
  FROM calls.call_disposition cd
  WHERE cd.call_type='INBOUND' AND cd.disposition='Agent Missed' AND (cd.service_id <> 1287 OR cd.ivr = 'Appointement/Other') AND cd.call_date BETWEEN '${from}' AND '${to}' AND cd.service_id IN (${serviceIds})
    AND EXISTS (SELECT 1 FROM calls.daywise_summary ds WHERE ds.service_id=cd.service_id AND ds.agent_name=cd.missed_by)
  GROUP BY cd.service_id, cd.missed_by, cd.call_date
) ami ON ami.service_id = dp.service_id AND ami.agent_name = cs.agent AND ami.call_date = cs.report_date
SET cs.agent_missed_ib = ami.agent_missed_ib
WHERE cs.report_date BETWEEN '${from}' AND '${to}' AND dp.service_id IN (${serviceIds});`;
return [{ json: { query } }];

const from = $('Set Date Range').first().json.from, to = $('Set Date Range').first().json.to, serviceIds = $('Set Date Range').first().json.serviceIds;
const query = `UPDATE calls.combined_summary cs
JOIN calls.dim_process dp ON dp.process_name = cs.process_name
JOIN (
  SELECT cd.service_id, cd.agent_number AS sip, cd.call_date, ROUND(AVG(cd.handle_time_sec)) AS aht_seconds
  FROM calls.call_disposition cd
  WHERE cd.call_type='INBOUND' AND cd.disposition='Answer' AND (cd.service_id <> 1287 OR cd.ivr = 'Appointement/Other') AND cd.call_date BETWEEN '${from}' AND '${to}' AND cd.service_id IN (${serviceIds})
    AND EXISTS (SELECT 1 FROM calls.daywise_summary ds WHERE ds.service_id=cd.service_id AND ds.agent_sip=cd.agent_number)
  GROUP BY cd.service_id, cd.agent_number, cd.call_date
) aht ON aht.service_id = dp.service_id AND aht.sip = cs.sip AND aht.call_date = cs.report_date
SET cs.aht = SEC_TO_TIME(aht.aht_seconds)
WHERE cs.report_date BETWEEN '${from}' AND '${to}';`;
return [{ json: { query } }];

const from = $('Set Date Range').first().json.from, to = $('Set Date Range').first().json.to, serviceIds = $('Set Date Range').first().json.serviceIds;
const query = `UPDATE calls.combined_summary cs
JOIN calls.dim_process dp ON dp.process_name = cs.process_name
JOIN calls.callback_on_missed_call cb ON cb.service_id = dp.service_id AND cb.report_date = cs.report_date
SET cs.callback_on_missed_call = SEC_TO_TIME(cb.avg_gap_seconds)
WHERE cs.report_date BETWEEN '${from}' AND '${to}' AND dp.service_id IN (${serviceIds});`;
return [{ json: { query } }];

const from = $('Set Date Range').first().json.from, to = $('Set Date Range').first().json.to, serviceIds = $('Set Date Range').first().json.serviceIds;
// Email tagging only exists for Baxter (489), ResMed (1702), and Facility
// (Infres 741 / VMM 295 / Nihon 338) -- narrow the IN() list to just those,
// so other processes are left untouched exactly like before (no-op), just
// via a normal WHERE filter now instead of a separate conditional branch.
const EMAIL_TAGGED_SERVICE_IDS = [489, 1702, 741, 295, 338];
const applicableIds = serviceIds.split(',').map(Number).filter(id => EMAIL_TAGGED_SERVICE_IDS.includes(id));
const query = applicableIds.length ? `UPDATE calls.combined_summary cs
JOIN calls.dim_process dp ON dp.process_name = cs.process_name
LEFT JOIN calls.email_tagged_daily et
  ON et.service_id = dp.service_id
  AND et.report_date = cs.report_date
  -- ResMed's Sagarika Bose is logged as 'Admin' in combined_summary but as her
  -- real name in email_tagged_daily -- map that one identity so the join finds her.
  AND (CASE WHEN dp.service_id = 1702 AND et.agent_name = 'Sagarika' THEN 'Sagarika Bose'
       WHEN dp.service_id = 1702 AND et.agent_name = 'Gulshan' THEN 'Gulshan Khan'
       WHEN dp.service_id = 1702 AND et.agent_name = 'Avijit' THEN 'Avijit Dey'
       ELSE et.agent_name END)
     = (CASE WHEN dp.service_id = 1702 AND cs.agent = 'Admin' THEN 'Sagarika Bose' ELSE cs.agent END)
SET cs.email_sent = COALESCE(et.email_count, 0),
    cs.email_duration = SEC_TO_TIME(COALESCE(et.email_count, 0) * 180)
WHERE dp.service_id IN (${applicableIds.join(',')}) AND cs.report_date BETWEEN '${from}' AND '${to}';` : 'SELECT 1;';
return [{ json: { query } }];
